CosmeticFiltersResourcesAsyncWaiter::CosmeticFiltersResourcesAsyncWaiter(
    CosmeticFiltersResources* proxy) : proxy_(proxy) {}

CosmeticFiltersResourcesAsyncWaiter::~CosmeticFiltersResourcesAsyncWaiter() = default;


void CosmeticFiltersResourcesAsyncWaiter::HiddenClassIdSelectors(
    const std::string& input, const std::vector<std::string>& exceptions, ::base::DictValue* out_result) {
  base::RunLoop loop;
  proxy_->HiddenClassIdSelectors(
      std::move(input),
      std::move(exceptions),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::DictValue* out_result
,
             ::base::DictValue result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

::base::DictValue CosmeticFiltersResourcesAsyncWaiter::HiddenClassIdSelectors(
    const std::string& input, const std::vector<std::string>& exceptions) {
  ::base::DictValue async_wait_result;
  HiddenClassIdSelectors(std::move(input),std::move(exceptions),&async_wait_result);
  return async_wait_result;
}

void CosmeticFiltersResourcesAsyncWaiter::UrlCosmeticResources(
    const std::string& url, bool aggressive_blocking, ::base::Value* out_result) {
  base::RunLoop loop;
  proxy_->UrlCosmeticResources(
      std::move(url),
      std::move(aggressive_blocking),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::Value* out_result
,
             ::base::Value result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

::base::Value CosmeticFiltersResourcesAsyncWaiter::UrlCosmeticResources(
    const std::string& url, bool aggressive_blocking) {
  ::base::Value async_wait_result;
  UrlCosmeticResources(std::move(url),std::move(aggressive_blocking),&async_wait_result);
  return async_wait_result;
}




