CosmeticFiltersHandlerAsyncWaiter::CosmeticFiltersHandlerAsyncWaiter(
    CosmeticFiltersHandler* proxy) : proxy_(proxy) {}

CosmeticFiltersHandlerAsyncWaiter::~CosmeticFiltersHandlerAsyncWaiter() = default;


void CosmeticFiltersHandlerAsyncWaiter::GetElementPickerThemeInfo(
    bool* out_is_dark_mode_enabled, int32_t* out_background_color) {
  base::RunLoop loop;
  proxy_->GetElementPickerThemeInfo(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_is_dark_mode_enabled
,
             int32_t* out_background_color
,
             bool is_dark_mode_enabled,
             int32_t background_color) {*out_is_dark_mode_enabled = std::move(is_dark_mode_enabled);*out_background_color = std::move(background_color);
            loop->Quit();
          },
          &loop,
          out_is_dark_mode_enabled,
          out_background_color));
  loop.Run();
}



void CosmeticFiltersHandlerAsyncWaiter::GetElementPickerLocalizedTexts(
    ElementPickerLocalizationPtr* out_localization_data) {
  base::RunLoop loop;
  proxy_->GetElementPickerLocalizedTexts(
      base::BindOnce(
          [](base::RunLoop* loop,
             ElementPickerLocalizationPtr* out_localization_data
,
             ElementPickerLocalizationPtr localization_data) {*out_localization_data = std::move(localization_data);
            loop->Quit();
          },
          &loop,
          out_localization_data));
  loop.Run();
}

ElementPickerLocalizationPtr CosmeticFiltersHandlerAsyncWaiter::GetElementPickerLocalizedTexts(
    ) {
  ElementPickerLocalizationPtr async_wait_result;
  GetElementPickerLocalizedTexts(&async_wait_result);
  return async_wait_result;
}




